"""Local-first image composer linked to the 65-person simulated trading ledger.

The uploaded template and rendered PNG stay in the user's browser. No image or
trade data is sent to a third-party editor.
"""

PAGE = r'''<!doctype html><html lang="zh-CN"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>交易图片与战绩 · NUVEXA</title>
<style>
:root{font-family:Inter,"Noto Sans SC","Microsoft YaHei",system-ui,sans-serif;color:#26313e;background:#f5f7f9}
*{box-sizing:border-box}body{margin:0;background:#f5f7f9;color:#26313e}.app{max-width:1600px;margin:auto;padding:22px clamp(14px,2.2vw,34px) 46px}
h1{font-size:clamp(23px,2.3vw,32px);margin:18px 0 7px;color:#17283b}h2{font-size:17px;margin:0 0 12px;color:#26394c}p{margin:0;color:#647282;line-height:1.65}
.head{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap}.head p{font-size:13px}.badge{display:inline-flex;border:1px solid #e4d7b6;background:#fffaf0;color:#795d24;padding:6px 10px;border-radius:99px;font-size:12px;font-weight:700}
.notice{margin:14px 0;padding:12px 15px;border:1px solid #e5dcc7;background:#fffdf8;border-radius:10px;color:#66552e;font-size:13px;line-height:1.65}
.card{background:#fff;border:1px solid #e2e7ed;border-radius:12px;padding:17px;min-width:0;box-shadow:0 3px 12px #18283a08}.top-grid{display:grid;grid-template-columns:minmax(280px,.72fr) minmax(0,1.6fr);gap:14px;align-items:start}.editor-grid{display:grid;grid-template-columns:minmax(250px,.7fr) minmax(0,1.3fr);gap:12px;margin-top:14px}.stack{display:grid;gap:14px}.field{display:grid;gap:6px;margin:11px 0}.field>span,.field label{font-size:12px;font-weight:700;color:#566576}.field input,.field select,.field textarea,.layer-row input{width:100%;min-height:38px;padding:8px 10px;border:1px solid #d6dee7;border-radius:8px;background:#fff;color:#26313e;font:inherit;font-size:13px}.field textarea{min-height:66px;resize:vertical}.field input:focus,.field select:focus,.field textarea:focus,.layer-row input:focus{outline:2px solid #7899ba;outline-offset:1px}
.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.button,.button-secondary,.button-link{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:39px;border:1px solid #213a55;border-radius:8px;padding:8px 12px;background:#193653;color:#fff;text-decoration:none;font:inherit;font-size:12px;font-weight:750;cursor:pointer}.button-secondary,.button-link{background:#fff;color:#30465d;border-color:#d2dae3}.button:disabled{opacity:.5;cursor:not-allowed}.button:hover{background:#102a45}.button-secondary:hover,.button-link:hover{background:#f3f6f8}.hint{font-size:11px;color:#778493;line-height:1.6}.status{margin-top:9px;min-height:22px;font-size:12px;color:#596a7b}.file-input{display:block;width:100%;padding:10px;border:1px dashed #bcc8d5;border-radius:9px;background:#fafbfd;font-size:12px}
.canvas-wrap{min-width:0;border:1px solid #dce3eb;border-radius:10px;background:#101a26;padding:10px;display:grid;place-items:center;min-height:300px;overflow:hidden}.canvas-wrap canvas{display:block;width:100%;max-height:70vh;object-fit:contain;touch-action:none;background:#f1f3f5}.canvas-empty{padding:40px 15px;text-align:center;color:#d2dbe5;font-size:13px}.layer-list{display:grid;gap:8px;max-height:660px;overflow:auto}.layer-row{display:grid;grid-template-columns:1fr 62px 62px 66px;gap:6px;align-items:center;padding:8px;border:1px solid #e7ebf0;border-radius:8px;background:#fbfcfd}.layer-row.selected{border-color:#52799c;background:#f1f6fa}.layer-row input{min-height:32px;padding:5px 7px;font-size:11px}.layer-row .layer-text{grid-column:1/-1}.layer-row label{display:grid;gap:3px;font-size:9px;color:#748091}.layer-row label input{width:100%}
.table-wrap{overflow:auto;border:1px solid #e1e6ec;border-radius:9px;max-height:440px}.table{border-collapse:collapse;width:100%;min-width:850px;font-size:12px}.table th,.table td{padding:10px 11px;text-align:left;border-bottom:1px solid #edf0f3;white-space:nowrap}.table th{position:sticky;top:0;background:#f4f6f8;color:#5c6a79;font-size:11px;z-index:1}.table td{color:#384859}.table tr:last-child td{border-bottom:0}.mono{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-variant-numeric:tabular-nums}.gain{color:#16825d;font-weight:700}.loss{color:#b44747;font-weight:700}.empty{padding:14px;color:#778493;font-size:12px}.mini{min-height:30px;padding:5px 8px;font-size:11px}.section-head{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:10px}.section-head h2{margin:0}.subnote{margin:-2px 0 11px;font-size:11px;color:#788594}
@media(max-width:980px){.top-grid,.editor-grid{grid-template-columns:1fr}.canvas-wrap canvas{max-height:60vh}.layer-list{max-height:none}}
@media(max-width:600px){.app{padding:14px 10px 30px}.card{padding:13px}.layer-row{grid-template-columns:1fr 54px 54px}.layer-row label:last-child{grid-column:1/-1}.table{min-width:760px}}
</style></head><body><main class="app">
<header class="head"><div><span class="badge">模拟账本联动 · 本地生成</span><h1>交易图片与战绩</h1><p>选择已确认卖出的模拟持仓，自动带入股票、数量、买入／卖出时间和价格，再套用你上传的图片模板。</p></div>
<div class="row"><a class="button-link" href="/trading">返回交易中心</a><button id="refresh" class="button-secondary" type="button">刷新交易记录</button></div></header>
<div class="notice"><strong>仅教学模拟：</strong>买卖记录来自本工作台的模拟账本，不代表真实证券成交、账户持仓或投资业绩。模板图片在当前浏览器内处理；不会上传至本工作台服务器或第三方图片站。</div>
<section class="top-grid">
<div class="stack">
<section class="card"><h2>1 · 选择卖出记录</h2><label class="field"><span>已确认卖出的模拟持仓</span><select id="saleSelect"><option value="">正在读取交易记录…</option></select></label><p class="hint">卖出后会自动跳转到此页并选中刚刚卖出的记录。也可在战绩表中点“做图片”。</p><div id="loadStatus" class="status" role="status">读取本地模拟账本中…</div></section>
<section class="card"><h2>2 · 上传你的模板</h2><input id="templateFile" class="file-input" type="file" accept="image/png,image/jpeg,image/webp"><p class="hint" style="margin-top:8px">支持 PNG、JPG、WebP。图片只在浏览器内打开；建议使用 16:9 横版模板。导出时按图片比例输出，长边最高 3840 px。</p><div class="field"><span>图片标题／补充说明</span><input id="headline" value="模拟卖出记录" maxlength="90"></div><div class="field"><span>备注</span><input id="caption" value="仅供内部教学记录 · 非真实成交" maxlength="160"></div><div class="row"><button id="resetFields" class="button-secondary" type="button">恢复字段默认值</button><button id="exportPng" class="button" type="button" disabled>下载 PNG 图片</button></div><div id="exportStatus" class="status" role="status"></div></section>
</div>
<section class="card"><div class="section-head"><h2>3 · 图片预览与字段位置</h2><span class="hint">选中字段后可拖动图片上的文字调整位置。</span></div><div id="canvasWrap" class="canvas-wrap"><div id="canvasEmpty" class="canvas-empty">先选择卖出记录并上传模板，图片将在这里预览</div><canvas id="preview" hidden aria-label="图片模板预览与字段文字"></canvas></div></section>
</section>
<section class="editor-grid">
<section class="card"><h2>可填写字段</h2><p class="subnote">成交相关字段自动读取模拟账本；你可按图片布局修改文字内容。时间按 Europe/Bucharest 显示。</p><div id="layers" class="layer-list"></div></section>
<section class="card"><div class="section-head"><h2>战绩表 · 买卖明细</h2><span class="badge">数据源：65 人模拟账本</span></div><p class="subnote">每行对应一笔持仓，买入与卖出时间、数量和成交模拟价来自已确认记录；收益不含费用。</p><div id="performance" class="table-wrap"><div class="empty">读取中…</div></div></section>
</section>
<section class="card" style="margin-top:14px"><div class="section-head"><h2>买卖流水</h2><span class="hint">买入和卖出分别显示精确记录时间与数量／价格。</span></div><div id="transactions" class="table-wrap"><div class="empty">读取中…</div></div></section>
</main>
<script>
(()=>{'use strict';
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtTime=v=>{if(!v)return '—';const d=new Date(v);if(Number.isNaN(d.getTime()))return '—';return new Intl.DateTimeFormat('zh-CN',{timeZone:'Europe/Bucharest',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(d)};
const fmtNum=v=>Number(v||0).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:4});
const fmtMoney=(v,c)=>`${c||''} ${fmtNum(v)}`.trim();
let state=null,template=null,activeHolding=null,layers=[],selectedLayer=-1,drag=null;
const canvas=$('preview'),ctx=canvas.getContext('2d');
const defaults=()=>[
 {key:'headline',label:'标题',text:'模拟卖出记录',x:50,y:9,size:36,color:'#ffffff',align:'center'},
 {key:'member',label:'成员',text:'',x:50,y:20,size:28,color:'#ffffff',align:'center'},
 {key:'symbol',label:'股票代码／名称',text:'',x:50,y:31,size:44,color:'#ffffff',align:'center'},
 {key:'quantity',label:'数量',text:'',x:50,y:42,size:30,color:'#ffffff',align:'center'},
 {key:'buyTime',label:'买入时间',text:'',x:50,y:53,size:25,color:'#ffffff',align:'center'},
 {key:'buyPrice',label:'买入价',text:'',x:50,y:61,size:25,color:'#ffffff',align:'center'},
 {key:'sellTime',label:'卖出时间',text:'',x:50,y:69,size:25,color:'#ffffff',align:'center'},
 {key:'sellPrice',label:'卖出价',text:'',x:50,y:77,size:25,color:'#ffffff',align:'center'},
 {key:'pnl',label:'模拟盈亏',text:'',x:50,y:85,size:34,color:'#a6f0c7',align:'center'},
 {key:'caption',label:'说明',text:'仅供内部教学记录 · 非真实成交',x:50,y:93,size:18,color:'#ffffff',align:'center'}
];
function personName(pid){return state?.people?.find(p=>p.id===pid)?.name||pid||'—'}
function rowsTable(heads,rows){return '<table class="table"><thead><tr>'+heads.map(x=>'<th>'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+rows+'</tbody></table>'}
function holdingLink(h){return '<a class="button-link mini" href="/image-editor?holding_id='+encodeURIComponent(h.id)+'">做图片</a>'}
function draw(){if(!template||!canvas.width)return;ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(template,0,0,canvas.width,canvas.height);layers.forEach((l,i)=>{const px=l.x/100*canvas.width,py=l.y/100*canvas.height;ctx.save();ctx.font=`700 ${Math.max(10,l.size/1600*canvas.width)}px Inter, "Noto Sans SC", sans-serif`;ctx.textAlign=l.align||'center';ctx.textBaseline='middle';ctx.fillStyle=l.color||'#fff';ctx.shadowColor='rgba(0,0,0,.66)';ctx.shadowBlur=Math.max(2,canvas.width*.0024);ctx.shadowOffsetX=0;ctx.shadowOffsetY=Math.max(1,canvas.width*.001);const maxW=canvas.width*(l.align==='center'?0.82:0.88);ctx.fillText(l.text||'',px,py,maxW);const m=ctx.measureText(l.text||'');ctx.restore();if(i===selectedLayer){const w=Math.min(m.width,canvas.width*.88),h=Math.max(22,l.size/1600*canvas.width*1.3);const left=l.align==='center'?px-w/2:l.align==='right'?px-w:px;ctx.save();ctx.setLineDash([8,6]);ctx.lineWidth=Math.max(2,canvas.width/800);ctx.strokeStyle='#ffd34f';ctx.strokeRect(left-8,py-h/2-5,w+16,h+10);ctx.restore();l.hit={x:left-10,y:py-h/2-7,w:w+20,h:h+14};}})}
function renderLayers(){const host=$('layers');host.innerHTML=layers.map((l,i)=>`<div class="layer-row ${i===selectedLayer?'selected':''}" data-layer="${i}"><label style="grid-column:1/-1">${esc(l.label)}<input class="layer-text" data-prop="text" value="${esc(l.text)}" maxlength="180" aria-label="${esc(l.label)}文字"></label><label>X %<input data-prop="x" type="number" min="0" max="100" step=".5" value="${l.x}"></label><label>Y %<input data-prop="y" type="number" min="0" max="100" step=".5" value="${l.y}"></label><label>字号<input data-prop="size" type="number" min="10" max="120" step="1" value="${l.size}"></label><label>颜色<input data-prop="color" type="color" value="${/^#[0-9a-f]{6}$/i.test(l.color)?l.color:'#ffffff'}"></label></div>`).join('');host.querySelectorAll('.layer-row').forEach(row=>{row.addEventListener('click',e=>{if(e.target.matches('input'))return;selectedLayer=Number(row.dataset.layer);renderLayers();draw()});row.querySelectorAll('input').forEach(input=>input.addEventListener('input',()=>{const i=Number(row.dataset.layer),p=input.dataset.prop;if(p==='x'||p==='y'||p==='size')layers[i][p]=Number(input.value);else layers[i][p]=input.value;selectedLayer=i;draw();row.classList.add('selected')}))})}
function updateLayer(key,text){const l=layers.find(x=>x.key===key);if(l)l.text=text}
function populateHolding(id){const h=state?.holdings?.find(x=>x.id===id);if(!h){$('loadStatus').textContent='找不到该模拟持仓记录。';return}activeHolding=h;const p=personName(h.person_id);const buyAt=h.buy_at||state.transactions.find(t=>t.holding_id===h.id&&t.type==='buy')?.created_at;const sellAt=h.sold_at||state.transactions.find(t=>t.holding_id===h.id&&t.type==='sell')?.created_at;const qty=Number(h.quantity||0),buy=Number(h.buy_price||0),sell=Number(h.sold_price||0);const pnl=(sell-buy)*qty,roi=buy?((sell/buy)-1)*100:0;layers=defaults();const vals={headline:'模拟卖出记录',member:`成员 ${h.person_id} · ${p}`,symbol:`${h.symbol||''} · ${h.name||''}`,quantity:`数量 ${qty} 股 · ${h.market||''}`,buyTime:`买入时间 ${fmtTime(buyAt)}`,buyPrice:`买入价 ${fmtMoney(buy,h.currency)}`,sellTime:`卖出时间 ${fmtTime(sellAt)}`,sellPrice:`卖出价 ${fmtMoney(sell,h.currency)}`,pnl:`模拟盈亏 ${fmtMoney(pnl,h.currency)} · ${roi>=0?'+':''}${roi.toFixed(2)}%`,caption:$('caption').value||'仅供内部教学记录 · 非真实成交'};layers.forEach(l=>l.text=vals[l.key]??l.text);$('headline').value=vals.headline;selectedLayer=0;renderLayers();$('saleSelect').value=h.id;$('loadStatus').textContent=`已载入 ${h.symbol} · ${p} · 买入 ${fmtTime(buyAt)} · 卖出 ${fmtTime(sellAt)}（布加勒斯特时间）` ;draw()}
function renderTables(){if(!state)return;const holds=[...(state.holdings||[])].sort((a,b)=>String(b.sold_at||b.buy_at||'').localeCompare(String(a.sold_at||a.buy_at||'')));const performance=holds.map(h=>{const buyEvent=state.transactions.find(t=>t.holding_id===h.id&&t.type==='buy');const sellEvent=state.transactions.find(t=>t.holding_id===h.id&&t.type==='sell');const buyAt=buyEvent?.created_at||h.buy_at,sellAt=sellEvent?.created_at||h.sold_at;const buy=Number(h.buy_price||0),sell=Number(h.sold_price||0),qty=Number(h.quantity||0),closed=h.status==='sold'&&sell>0;const pnl=closed?(sell-buy)*qty:null,roi=closed&&buy?((sell/buy)-1)*100:null;const result=closed?`<span class="${pnl>=0?'gain':'loss'}">${pnl>=0?'+':''}${esc(fmtMoney(pnl,h.currency))} (${roi>=0?'+':''}${roi.toFixed(2)}%)</span>`:'持有中';return `<tr><td>${esc(personName(h.person_id))}</td><td><span class="mono">${esc(h.symbol)}</span><br><span class="hint">${esc(h.name)}</span></td><td>${esc(fmtTime(buyAt))}</td><td>${esc(fmtMoney(buy,h.currency))}</td><td>${esc(h.quantity)} 股</td><td>${closed?esc(fmtTime(sellAt)):'—'}</td><td>${closed?esc(fmtMoney(sell,h.currency)):'—'}</td><td>${result}</td><td>${closed?holdingLink(h):'—'}</td></tr>`}).join('');$('performance').innerHTML=performance?rowsTable(['成员','证券','买入时间','买入模拟价','数量','卖出时间','卖出模拟价','模拟损益¹','图片'],performance):'<div class="empty">暂无模拟买卖记录。先到交易中心建立计划并确认买入。</div>';const tx=[...(state.transactions||[])].sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||''))).map(t=>{const h=state.holdings.find(x=>x.id===t.holding_id)||{};return `<tr><td>${esc(t.type==='buy'?'买入':'卖出')}</td><td>${esc(personName(t.person_id))}</td><td>${esc(h.symbol||'—')} · ${esc(h.name||'')}</td><td>${esc(t.quantity)} 股</td><td>${esc(fmtMoney(t.unit_price,t.currency))}</td><td>${esc(fmtTime(t.created_at))}</td><td class="mono">${esc(t.id)}</td></tr>`}).join('');$('transactions').innerHTML=tx?rowsTable(['方向','成员','证券','数量','模拟成交价','记录时间（布加勒斯特）','记录编号'],tx):'<div class="empty">暂无人工确认的模拟成交。</div>';const sold=holds.filter(h=>h.status==='sold');$('saleSelect').innerHTML='<option value="">选择一笔已卖出的模拟记录</option>'+sold.map(h=>`<option value="${esc(h.id)}">${esc(h.symbol)} · ${esc(personName(h.person_id))} · ${esc(fmtTime(h.sold_at))}</option>`).join('')}
async function load(){try{const r=await fetch('/api/trading/sim/state',{credentials:'same-origin',cache:'no-store'});const d=await r.json();if(!r.ok)throw Error(d.error||'HTTP '+r.status);state=d;renderTables();$('loadStatus').textContent=`账本已同步：${d.holdings.length} 笔持仓，${d.transactions.length} 笔买卖流水。`;const requested=new URLSearchParams(location.search).get('holding_id');if(requested&&state.holdings.some(h=>h.id===requested))populateHolding(requested);else if(!activeHolding&&state.holdings.some(h=>h.status==='sold'))$('saleSelect').value='';}catch(e){$('loadStatus').textContent='读取交易账本失败：'+e.message;$('performance').innerHTML='<div class="empty">无法读取战绩数据。请返回交易中心检查本地服务。</div>';$('transactions').innerHTML='<div class="empty">无法读取买卖流水。</div>'}}
$('saleSelect').addEventListener('change',()=>{if($('saleSelect').value)populateHolding($('saleSelect').value)});$('refresh').addEventListener('click',()=>load());$('headline').addEventListener('input',()=>{updateLayer('headline',$('headline').value);renderLayers();draw()});$('caption').addEventListener('input',()=>updateLayer('caption',$('caption').value));$('resetFields').addEventListener('click',()=>{if(activeHolding)populateHolding(activeHolding.id);else{layers=defaults();renderLayers();draw()}});
$('templateFile').addEventListener('change',e=>{const file=e.target.files?.[0];if(!file)return;if(!/^image\/(png|jpeg|webp)$/.test(file.type)){ $('exportStatus').textContent='请选择 PNG、JPG 或 WebP 图片。';return;}const url=URL.createObjectURL(file),im=new Image();im.onload=()=>{template=im;canvas.width=1600;canvas.height=Math.round(1600*im.naturalHeight/im.naturalWidth);canvas.hidden=false;$('canvasEmpty').hidden=true;$('exportPng').disabled=false;draw();$('exportStatus').textContent=`模板已载入：${file.name} · ${im.naturalWidth} × ${im.naturalHeight}。图片仅保留在当前页面内存中。`;URL.revokeObjectURL(url)};im.onerror=()=>{$('exportStatus').textContent='无法读取图片文件。';URL.revokeObjectURL(url)};im.src=url});
canvas.addEventListener('pointerdown',e=>{if(!template)return;const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*canvas.width,y=(e.clientY-r.top)/r.height*canvas.height;let i=-1;for(let j=layers.length-1;j>=0;j--){const a=layers[j].hit;if(a&&x>=a.x&&x<=a.x+a.w&&y>=a.y&&y<=a.y+a.h){i=j;break}}if(i<0)return;selectedLayer=i;drag={i};canvas.setPointerCapture(e.pointerId);renderLayers();draw()});canvas.addEventListener('pointermove',e=>{if(!drag)return;const r=canvas.getBoundingClientRect(),l=layers[drag.i];l.x=Math.max(0,Math.min(100,(e.clientX-r.left)/r.width*100));l.y=Math.max(0,Math.min(100,(e.clientY-r.top)/r.height*100));draw()});canvas.addEventListener('pointerup',()=>{if(!drag)return;drag=null;renderLayers();draw()});canvas.addEventListener('pointercancel',()=>{drag=null});
$('exportPng').addEventListener('click',()=>{if(!template){$('exportStatus').textContent='请先上传模板图片。';return}try{const scale=3840/Math.max(template.naturalWidth,template.naturalHeight),w=Math.round(template.naturalWidth*scale),h=Math.round(template.naturalHeight*scale),out=document.createElement('canvas');out.width=w;out.height=h;const c=out.getContext('2d');if(!c)throw Error('浏览器无法创建画布');c.drawImage(template,0,0,w,h);for(const l of layers){c.save();c.font=`700 ${Math.max(12,l.size/1600*w)}px Inter, "Noto Sans SC", sans-serif`;c.textAlign=l.align||'left';c.textBaseline='middle';c.fillStyle=l.color||'#fff';c.shadowColor='rgba(0,0,0,.66)';c.shadowBlur=w*.0024;c.shadowOffsetY=w*.001;c.fillText(l.text||'',l.x/100*w,l.y/100*h,w*.88);c.restore()}const a=document.createElement('a');const sym=(activeHolding?.symbol||'template').replace(/[^A-Za-z0-9_-]/g,'_');a.download=`simulated-sell-${sym}-${new Date().toISOString().slice(0,10)}.png`;a.href=out.toDataURL('image/png');a.click();$('exportStatus').textContent=`PNG 已在本机生成（${w} × ${h}）。记录内容仍是教学模拟数据。`}catch(e){$('exportStatus').textContent='导出失败：'+e.message}});
load();
})();
</script></body></html>'''
